            label: 'Cần ôn tập',
            sublabel: overdue === 0 ? 'Hôm nay' : `Quá ${overdue} ngày`,
            icon: '🔥',
            color: 'text-orange-600',
            bg: 'bg-orange-50',
            border: 'border-orange-300'
